function tokenize(src) {
  const out = [];
  let i = 0;
  while (i < src.length) {
    const c = src[i];
    if (/\s/.test(c)) { i++; continue; }                       // 공백 버림
    if (/[0-9]/.test(c)) {                                     // 숫자
      let s = i;
      while (i < src.length && /[0-9.]/.test(src[i])) i++;
      out.push({ type: 'num', value: Number(src.slice(s, i)), at: s });
      continue;
    }
    if (/[a-zA-Z_]/.test(c)) {                                 // 이름
      let s = i;
      while (i < src.length && /[a-zA-Z0-9_]/.test(src[i])) i++;
      out.push({ type: 'name', value: src.slice(s, i), at: s });
      continue;
    }
    if ('+-*/()'.includes(c)) { out.push({ type: c, at: i }); i++; continue; }
    throw new Error(`모르는 글자 '${c}' (위치 ${i})`);
  }
  out.push({ type: 'eof', at: src.length });                   // 끝 표시
  return out;
}
